import OpenAI from "openai";

// the newest OpenAI model is "gpt-4o" which was released May 13, 2024. do not change this unless explicitly requested by the user
const openai = new OpenAI({ 
  apiKey: process.env.OPENAI_API_KEY || process.env.OPENAI_API_KEY_ENV_VAR || "default_key"
});

export interface HealthAnalysisResult {
  overallHealthScore: number;
  cardiacRisk: number;
  fitnessLevel: number;
  insights: Array<{
    type: 'positive' | 'warning' | 'info';
    title: string;
    description: string;
  }>;
  recommendations: string[];
  predictiveScore: number;
  riskFactors: string[];
}

export async function analyzeHealthData(healthData: any): Promise<HealthAnalysisResult> {
  try {
    const prompt = `
You are a medical AI assistant analyzing health data. Analyze the following health data and provide insights:

Health Data: ${JSON.stringify(healthData)}

Please provide a comprehensive health analysis in JSON format with the following structure:
{
  "overallHealthScore": number (0-100),
  "cardiacRisk": number (0-100),
  "fitnessLevel": number (0-100),
  "insights": [
    {
      "type": "positive" | "warning" | "info",
      "title": "string",
      "description": "string"
    }
  ],
  "recommendations": ["string"],
  "predictiveScore": number (0-100),
  "riskFactors": ["string"]
}

Focus on:
- Blood pressure analysis
- Heart rate patterns
- BMI and weight trends
- Risk assessment for cardiovascular disease
- Actionable recommendations
- Predictive health outlook

Ensure all scores are realistic and evidence-based.
`;

    const response = await openai.chat.completions.create({
      model: "gpt-4o",
      messages: [
        {
          role: "system",
          content: "You are an expert medical AI assistant providing health analysis based on patient data. Always provide evidence-based insights and recommendations."
        },
        {
          role: "user",
          content: prompt
        }
      ],
      response_format: { type: "json_object" },
      temperature: 0.3,
    });

    const result = JSON.parse(response.choices[0].message.content || "{}");

    // Validate and ensure all required fields are present
    return {
      overallHealthScore: Math.max(0, Math.min(100, result.overallHealthScore || 75)),
      cardiacRisk: Math.max(0, Math.min(100, result.cardiacRisk || 30)),
      fitnessLevel: Math.max(0, Math.min(100, result.fitnessLevel || 70)),
      insights: result.insights || [],
      recommendations: result.recommendations || [],
      predictiveScore: Math.max(0, Math.min(100, result.predictiveScore || 80)),
      riskFactors: result.riskFactors || [],
    };
  } catch (error) {
    throw new Error("Failed to analyze health data: " + (error as Error).message);
  }
}

export async function generateHealthInsights(analysisHistory: any[]): Promise<string[]> {
  try {
    const prompt = `
Based on the following health analysis history, generate personalized health insights and trends:

Analysis History: ${JSON.stringify(analysisHistory)}

Provide 3-5 key insights about health trends, improvements, or areas of concern.
Return as a JSON array of strings.
`;

    const response = await openai.chat.completions.create({
      model: "gpt-4o",
      messages: [
        {
          role: "system",
          content: "You are a health insights expert providing trend analysis based on historical health data."
        },
        {
          role: "user",
          content: prompt
        }
      ],
      response_format: { type: "json_object" },
      temperature: 0.4,
    });

    const result = JSON.parse(response.choices[0].message.content || '{"insights": []}');
    return result.insights || [];
  } catch (error) {
    throw new Error("Failed to generate health insights: " + (error as Error).message);
  }
}

